    private static let families: [(prefix: String, en: String, fr: String)] = [
        ("mail_", "Mail", "Mail"), ("notes_", "Notes", "Notes"), ("calendar_", "Calendar", "Calendrier"),
        ("reminders_", "Reminders", "Rappels"), ("messages_", "Messages", "Messages"), ("contacts_", "Contacts", "Contacts"),
    ]

    public static func title(_ name: String, running: Bool = false, locale: Locale = .current) -> String {
        let fr = TurnLayoutText.french(locale)
        if name.hasPrefix("Provider · ") { return name }
        if let entry = names[name] { return fr ? (running ? entry.3 : entry.2) : (running ? entry.1 : entry.0) }
        if let family = families.first(where: { name.hasPrefix($0.prefix) }) {
            return fr ? (running ? "Utilisation de \(family.fr)" : "\(family.fr) utilisé") : (running ? "Using \(family.en)" : "Used \(family.en)")
        }
        if name.hasPrefix("bg_") { return fr ? "Action dans une app en arrière-plan" : "Worked in an app in the background" }
        if name.hasPrefix("plugin_") || name.hasPrefix("mcp_") { return fr ? (running ? "Utilisation d'une extension" : "Extension utilisée") : (running ? "Using an extension" : "Used an extension") }
        return fr ? (running ? "Utilisation d'un outil" : "Outil utilisé") : (running ? "Using a tool" : "Used a tool")
    }
